// Get data from the node before this one
const data = $input.item.json;

// Extract property details
const price = data.price ? `${data.price.toLocaleString()}` : 'N/A';
const address = data.address?.streetAddress || 'Unknown Address';
const city = data.address?.city || '';
const state = data.address?.state || '';
const fullAddress = `${address}, ${city}, ${state}`;
const beds = data.bedrooms ? `${data.bedrooms} bd` : 'N/A';
const baths = data.bathrooms ? `${data.bathrooms} ba` : 'N/A';
const sqft = data.livingArea ? `${data.livingArea.toLocaleString()} sqft` : 'N/A';
const description = data.description || data.resoFacts?.description || '';

// --- New Image Selection Logic ---

// 1. Get all images with captions
const allImages = (data.photos || [])
  .map((photo, i) => ({
    url: photo.url || photo.mixedSources?.jpeg[photo.mixedSources.jpeg.length - 1]?.url,
    caption: (photo.caption || '').toLowerCase(),
    index: i
  }))
  .filter(photo => photo.url); // Ensure we only have images with a valid URL

// 2. Define our keywords
const interiorKeywords = ['kitchen', 'living', 'bedroom', 'master', 'bath', 'dining', 'basement', 'interior', 'great room', 'family room'];
const exteriorKeywords = ['exterior', 'front', 'yard', 'backyard', 'patio', 'deck', 'pool', 'aerial', 'view', 'outside'];

// 3. Filter images into buckets
const interiorImages = [];
const exteriorImages = [];
const otherImages = [];

for (const img of allImages) {
  if (interiorKeywords.some(k => img.caption.includes(k))) {
    interiorImages.push(img);
  } else if (exteriorKeywords.some(k => img.caption.includes(k))) {
    exteriorImages.push(img);
  } else {
    otherImages.push(img);
  }
}

// 4. Select our 3 images (2 interior, 1 exterior)
const selectedImages = [];
selectedImages.push(...interiorImages.slice(0, 2));
selectedImages.push(...exteriorImages.slice(0, 1));

// 5. Fallback: If we don't have 3 images yet, fill with 'other' images
let needed = 3 - selectedImages.length;
if (needed > 0) {
  selectedImages.push(...otherImages.slice(0, needed));
}

// 6. Final Fallback: If still not enough, just take the first 3 images from the total list
needed = 3 - selectedImages.length;
if (needed > 0) {
  const existingUrls = selectedImages.map(img => img.url);
  const fallback = allImages.filter(img => !existingUrls.includes(img.url)).slice(0, needed);
  selectedImages.push(...fallback);
}

// Return the final data
return {
  price,
  address: fullAddress,
  beds,
  baths,
  sqft,
  description: description.slice(0, 500),
  images: selectedImages.map(img => img.url), // This is now an array of up to 3 URLs
  imageCount: selectedImages.length,
  name: $input.item.json.name,   
  email: $input.item.json.email  
};

